window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-channels-wa-api.html"]="<!-- Settings: WhatsApp API Channel -->\n<style>\n.st-wa-status{display:flex;align-items:center;gap:12px;margin-bottom:20px;padding:16px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius)}\n.st-wa-status .dot{width:10px;height:10px;border-radius:50%;flex-shrink:0}\n.st-wa-status .dot.on{background:var(--ok)}.st-wa-status .dot.off{background:var(--danger)}\n.st-wa-info{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:20px}\n.st-wa-info .card{padding:14px}.st-wa-info .card .label{font-size:12px;color:var(--muted);margin-bottom:4px}\n.st-wa-info .card .value{font-size:15px;font-weight:600}\n.st-form label{display:block;font-size:13px;font-weight:500;margin-bottom:14px}\n.st-form label input,.st-form label select{display:block;width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:8px;margin-top:4px;font-size:14px;background:var(--bg)}\n.st-form label input:focus,.st-form label select:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.badge{display:inline-block;padding:3px 10px;border-radius:10px;font-size:11px;font-weight:700}\n.badge.ok{background:#dcfce7;color:#15803d}.badge.err{background:#fef2f2;color:var(--danger)}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">Role & Izin</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/channels-whatsapp-api')\">WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin-bottom:4px\">WhatsApp API</h2>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:20px\">Konfigurasi koneksi WhatsApp Business API (Meta Cloud API).</p>\n\n    <div class=\"st-wa-status\" id=\"waApiStatus\">\n      <span class=\"dot\" id=\"waApiDot\"></span>\n      <span id=\"waApiBadge\"></span>\n      <span style=\"margin-left:auto;font-size:13px;color:var(--muted)\" id=\"waApiNumber\"></span>\n    </div>\n\n    <div class=\"st-wa-info\">\n      <div class=\"card\"><div class=\"label\">Provider</div><div class=\"value\" id=\"waApiProvider\">-</div></div>\n      <div class=\"card\"><div class=\"label\">Nomor Terdaftar</div><div class=\"value\" id=\"waApiNum\">-</div></div>\n    </div>\n\n    <h3 style=\"margin-bottom:12px\">Edit Konfigurasi</h3>\n    <div class=\"st-form card\" style=\"max-width:480px\">\n      <label>Nomor Telepon<input id=\"waApiEditNum\" placeholder=\"+628xxxx\"></label>\n      <label>Provider<select id=\"waApiEditProv\">\n        <option value=\"Meta Cloud API\">Meta Cloud API</option>\n        <option value=\"Wablas\">Wablas</option>\n        <option value=\"Zenziva\">Zenziva</option>\n        <option value=\"Qontak\">Qontak</option>\n      </select></label>\n      <label>API Token<input id=\"waApiEditToken\" type=\"password\" placeholder=\"Token API\"></label>\n      <div style=\"display:flex;gap:8px;justify-content:flex-end;margin-top:8px\">\n        <button class=\"btn primary\" onclick=\"saveWaApi()\">Simpan</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  const c=DB.settings.channels.whatsappApi;\n  document.getElementById('waApiDot').className='dot '+(c.connected?'on':'off');\n  document.getElementById('waApiBadge').innerHTML=c.connected\n    ?'<span class=\"badge ok\">Terhubung</span>'\n    :'<span class=\"badge err\">Terputus</span>';\n  document.getElementById('waApiNumber').textContent=c.number||'-';\n  document.getElementById('waApiProvider').textContent=c.provider||'-';\n  document.getElementById('waApiNum').textContent=c.number||'-';\n  document.getElementById('waApiEditNum').value=c.number||'';\n  document.getElementById('waApiEditProv').value=c.provider||'Meta Cloud API';\n})();\n\nfunction saveWaApi(){\n  const num=document.getElementById('waApiEditNum').value.trim();\n  const prov=document.getElementById('waApiEditProv').value;\n  if(!num){showToast('Nomor telepon wajib diisi');return}\n  DB.settings.channels.whatsappApi={...DB.settings.channels.whatsappApi,number:num,provider:prov,connected:true};\n  saveStore();\n  showToast('Konfigurasi WhatsApp API berhasil disimpan');\n  go('settings/channels-whatsapp-api');\n}\n</script>\n";
